import data.glitch_lib

# Helper function to find the last condition in a chain
find_last_condition(cond) = last {
    cond.else_statement == null
    last := cond
}

find_last_condition(cond) = last {
    cond.else_statement != null
    last := find_last_condition(cond.else_statement)
}

# Check if a chain of conditionals has a default case
has_default_in_chain(cond) = has_default {
    current := cond
    while current != null {
        if current.is_default {
            has_default := true
            break
        }
        current := current.else_statement
    }
    has_default := false
}

